insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000018'::uuid,0,'Assaisonner le poulet de sel et poivre. Le faire dorer dans une cocotte avec une petite quantité de matière grasse, puis réserver.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000018'::uuid,1,'Dans la même cocotte, cuire l’oignon et l’ail jusqu’à tendreté. Ajouter la sauce ou le concentré de noix de palme puis le bouillon et mélanger.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000018'::uuid,2,'Remettre le poulet dans la sauce. Couvrir partiellement et laisser mijoter environ 45 à 55 minutes, jusqu’à ce que le poulet soit tendre et la sauce épaisse.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000018'::uuid,3,'Pour le saka-saka, cuire l’oignon dans l’huile de palme, ajouter les feuilles de manioc préparées et l’eau. Laisser mijoter doucement 35 à 45 minutes jusqu’à texture fondante.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000018'::uuid,4,'Cuire le riz blanc séparément selon la méthode habituelle, puis l’aérer à la fourchette.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000018'::uuid,5,'Dresser chaque assiette avec riz blanc, poulet nappé de sauce moambé et une généreuse portion de saka-saka afin de correspondre à la présentation photographiée à Kinshasa.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000019'::uuid,0,'Mélanger l’eau tiède, le sucre et la levure. Laisser reposer 5 minutes.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000019'::uuid,1,'Ajouter la farine et le sel. Mélanger vigoureusement pour obtenir une pâte très souple, collante et uniforme.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000019'::uuid,2,'Couvrir et laisser lever 60 à 90 minutes, jusqu’à ce que la pâte soit gonflée et remplie de bulles.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000019'::uuid,3,'Chauffer l’huile à environ 175 °C. Mouiller légèrement les doigts ou utiliser deux cuillères pour prélever de petites portions de pâte.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000019'::uuid,4,'Déposer les portions dans l’huile sans surcharger la casserole. Frire en les retournant jusqu’à ce qu’elles soient uniformément dorées.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000019'::uuid,5,'Égoutter sur papier absorbant et servir chaud ou tiède, sans garniture additionnelle afin de conserver la présentation simple de la photo de référence.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000020'::uuid,0,'Mélanger le poisson avec les oignons, les piments, les herbes, le sel et l’huile. Laisser reposer 15 minutes.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000020'::uuid,1,'Assouplir rapidement les feuilles au-dessus d’une chaleur douce afin qu’elles puissent se plier sans casser.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000020'::uuid,2,'Superposer plusieurs feuilles et déposer le poisson assaisonné au centre. Replier soigneusement pour former un paquet bien fermé et l’attacher.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000020'::uuid,3,'Cuire le paquet sur une grille ou dans une casserole couverte à chaleur modérée environ 35 à 45 minutes, en le retournant une fois si la chaleur vient du dessous.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000020'::uuid,4,'Vérifier que le poisson est entièrement cuit. Ouvrir prudemment le paquet en évitant la vapeur chaude.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000020'::uuid,5,'Servir directement dans les feuilles ou transvaser sur une assiette; les feuilles servent à la cuisson et ne sont pas consommées.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000021'::uuid,0,'Utiliser uniquement une pâte de manioc fermentée vendue comme aliment prêt à cuire. Ne pas improviser la détoxification ou la fermentation de manioc amer cru.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000021'::uuid,1,'Pétrir la pâte jusqu’à texture uniforme. Ajouter un peu d’eau seulement si elle est trop sèche pour être façonnée.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000021'::uuid,2,'Former deux à quatre cylindres compacts. Assouplir brièvement les feuilles de bananier à la chaleur.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000021'::uuid,3,'Envelopper chaque cylindre très serré dans plusieurs couches de feuilles, puis attacher les paquets.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000021'::uuid,4,'Cuire à la vapeur 60 à 75 minutes, jusqu’à ce que la pâte soit ferme, dense et complètement chauffée à cœur.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000021'::uuid,5,'Laisser tiédir avant de déballer et couper en morceaux. Servir comme accompagnement de sauces, ragoûts ou viandes grillées.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000022'::uuid,0,'Chauffer l’huile dans une grande cocotte. Faire revenir les oignons puis ajouter le poulet, gingembre, curcuma, ras el-hanout, safran, sel et poivre.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000022'::uuid,1,'Ajouter les tomates et les carottes, puis verser environ 1 litre d’eau. Couvrir et laisser mijoter 35 minutes.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000022'::uuid,2,'Ajouter les lentilles et le fenugrec égoutté. Compléter avec un peu d’eau si nécessaire et poursuivre la cuisson 35 à 45 minutes, jusqu’à ce que le poulet et les lentilles soient tendres.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000022'::uuid,3,'Retirer le poulet lorsqu’il est cuit. Laisser réduire la sauce quelques minutes : elle doit rester abondante pour imbiber le pain.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000022'::uuid,4,'Déchirer le msemen ou le trid en morceaux et les disposer dans un grand plat de service.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000022'::uuid,5,'Arroser généreusement le pain de sauce aux lentilles et fenugrec, puis déposer le poulet et les légumes au-dessus. Servir très chaud.',null,null);
