values ('10000000-0000-4000-8000-000000000022'::uuid,'ac515660-4852-4ebd-8cb5-3348d60e06e9'::uuid,'Rfissa de Fès au poulet et lentilles','rfissa-fes-poulet-lentilles','Rfissa marocaine de poulet avec lentilles, fenugrec, oignons, tomates et carottes, servie sur des morceaux de msemen ou de trid.','Poulet, lentilles et fenugrec sur msemen, photographiés à Fès.','fr','MA','Fès','Poulet et pain','adapted'::public.recipe_authenticity,'published'::public.recipe_status,'hard'::public.recipe_difficulty,35,90,6.00,now(),(select id from public.culinary_places where slug='ma-fez'),true,'Wikimedia Commons — rfissa photographiée à Fès','https://commons.wikimedia.org/wiki/File:Rfissa_is_a_beyond_delicious_meal.jpg','La photo a été faite à Fès et sa description cite directement lentilles, fenugrec, poulet, tomates, oignons et carottes. Ces éléments sont tous intégrés à la recette.')
